actions.script:
const yr = ec.l10n.format(declarationDate, 'yyyy');
// Auto sequence for customs VAT protocol
const prefix = vatRegisterSeries + '-' + yr + '-';
const countFind = ec.entity.find('mantle.account.invoice.Invoice')
    .condition('vatRegisterSeries', vatRegisterSeries)
    .condition('vatProtocolDate', 'greater-equals', yr + '-01-01')
    .condition('vatProtocolDate', 'less-equals', yr + '-12-31');
const existing = countFind.list();
const nextSeq = (existing ? existing.length : 0) + 1;
context.vatProtocolNum = prefix + String(nextSeq).padStart(4, '0');

service-call.in-map:
{
                invoiceId: vatRegisterInvoiceId,
                vatProtocolNum: vatProtocolNum,
                vatProtocolDate: declarationDate,
                vatRegisterSeries: vatRegisterSeries
            }
